dataSet.query:
ВЫБРАТЬ РАЗЛИЧНЫЕ Сегменты.Номенклатура, Сегменты.Характеристика, ИСТИНА КАК ИспользуетсяОтборПоСегментуНоменклатуры ПОМЕСТИТЬ ОтборПоСегментуНоменклатуры ИЗ РегистрСведений.НоменклатураСегмента КАК Сегменты {ГДЕ Сегменты.Сегмент.* КАК СегментНоменклатуры, Сегменты.Номенклатура.* КАК Номенклатура, Сегменты.Характеристика.* КАК Характеристика}
ИНДЕКСИРОВАТЬ ПО Сегменты.Номенклатура, Сегменты.Характеристика, ИспользуетсяОтборПоСегментуНоменклатуры ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ Сегменты.Партнер КАК Партнер, ИСТИНА КАК ИспользуетсяОтборПоСегментуПартнеров ПОМЕСТИТЬ ОтборПоСегментуПартнеров {ВЫБРАТЬ Партнер.*} ИЗ РегистрСведений.ПартнерыСегмента КАК Сегменты {ГДЕ Сегменты.Сегмент.* КАК СегментПартнеров, Сегменты.Партнер.* КАК Партнер}
ИНДЕКСИРОВАТЬ ПО Сегменты.Партнер ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ СУММА(Таблица.Количество) КАК Количество, ВЫБОР КОГДА &ДанныеПоПродажам = 1 ТОГДА СУММА(Таблица.Выручка) КОГДА &ДанныеПоПродажам = 3 ТОГДА СУММА(Таблица.ВыручкаРегл) ИНАЧЕ СУММА(Таблица.ВыручкаБезНДС) КОНЕЦ КАК Выручка, СУММА(Таблица.Выручка) - СУММА(Таблица.ВыручкаБезНДС) КАК ВыручкаНДС, ВЫБОР КОГДА &ДанныеПоПродажам = 1 ТОГДА СУММА(Таблица.Стоимость) КОГДА &ДанныеПоПродажам = 3 ТОГДА СУММА(Таблица.СтоимостьРегл) ИНАЧЕ СУММА(Таблица.СтоимостьБезНДС) КОНЕЦ КАК Себестоимость, ВЫБОР КОГДА &ДанныеПоПродажам = 1 ТОГДА СУММА(Таблица.ДопРасходы) КОГДА &ДанныеПоПродажам = 3 ТОГДА 0 ИНАЧЕ СУММА(Таблица.ДопРасходыБезНДС) КОНЕЦ КАК ДопРасходы, ВЫБОР КОГДА &ДанныеПоПродажам = 1 ТОГДА СУММА(Таблица.Выручка) - СУММА(Таблица.Стоимость) - СУММА(Таблица.ДопРасходы) КОГДА &ДанныеПоПродажам = 3 ТОГДА СУММА(Таблица.ВыручкаРегл) - СУММА(Таблица.СтоимостьРегл) ИНАЧЕ СУММА(Таблица.ВыручкаБезНДС) - СУММА(Таблица.СтоимостьБезНДС) - СУММА(Таблица.ДопРасходыБезНДС) КОНЕЦ КАК ВаловаяПрибыль, ВЫБОР КОГДА &ДанныеПоПродажам = 1 ТОГДА ВЫРАЗИТЬ(ВЫБОР КОГДА СУММА(Таблица.Выручка) <> 0 ТОГДА (СУММА(Таблица.Выручка) - СУММА(Таблица.Стоимость) - СУММА(Таблица.ДопРасходы)) / СУММА(Таблица.Выручка) ИНАЧЕ 0 КОНЕЦ * 100 КАК ЧИСЛО(15, 2)) КОГДА &ДанныеПоПродажам = 3 ТОГДА ВЫРАЗИТЬ(ВЫБОР КОГДА СУММА(Таблица.ВыручкаРегл) <> 0 ТОГДА (СУММА(Таблица.ВыручкаРегл) - СУММА(Таблица.СтоимостьРегл)) / СУММА(Таблица.ВыручкаРегл) ИНАЧЕ 0 КОНЕЦ * 100 КАК ЧИСЛО(15, 2)) ИНАЧЕ ВЫРАЗИТЬ(ВЫБОР КОГДА СУММА(Таблица.ВыручкаБезНДС) <> 0 ТОГДА (СУММА(Таблица.ВыручкаБезНДС) - СУММА(Таблица.СтоимостьБезНДС) - СУММА(Таблица.ДопРасходыБезНДС)) / СУММА(Таблица.ВыручкаБезНДС) ИНАЧЕ 0 КОНЕЦ * 100 КАК ЧИСЛО(15, 2)) КОНЕЦ КАК Рентабельность, ВЫБОР КОГДА Таблица.Партнер = ЗНАЧЕНИЕ(Справочник.Партнеры.НашеПредприятие) ТОГДА ИСТИНА ИНАЧЕ ЛОЖЬ КОНЕЦ КАК ПродажиМеждуОрганизациями, Таблица.Номенклатура КАК Номенклатура, Таблица.Характеристика КАК Характеристика, Таблица.Организация КАК Организация, Таблица.Продавец КАК Продавец, Таблица.Партнер КАК Партнер, Таблица.ЗаказКлиента КАК ЗаказКлиента, Таблица.Подразделение КАК Подразделение, Таблица.Склад КАК Склад, Таблица.Контрагент КАК Контрагент, Таблица.Покупатель КАК Покупатель, Таблица.Поставщик КАК Поставщик, Таблица.Менеджер КАК Менеджер, Таблица.Сделка КАК Сделка, Таблица.МенеджерСделки КАК МенеджерСделки, Таблица.ВидЗапасов КАК ВидЗапасов, Таблица.ГруппаФинансовогоУчета КАК ГруппаФинансовогоУчета, Таблица.ВидСделки КАК ВидСделки, Таблица.Регистратор КАК Регистратор, Таблица.ПериодСекунда КАК ПериодСекунда, Таблица.День КАК День, Таблица.Неделя КАК Неделя, Таблица.Декада КАК Декада, Таблица.Месяц КАК Месяц, Таблица.Квартал КАК Квартал, Таблица.Полугодие КАК Полугодие, Таблица.Год КАК Год, ВЫБОР КОГДА Таблица.Партнер.ДатаРегистрации >= &НачалоПериода ТОГДА ИСТИНА ИНАЧЕ ЛОЖЬ КОНЕЦ КАК ЭтоНовый ПОМЕСТИТЬ ПродажиВсе {ВЫБРАТЬ Количество, Выручка, ВыручкаНДС, Себестоимость, ДопРасходы, ВаловаяПрибыль, Рентабельность, ПродажиМеждуОрганизациями, Номенклатура.*, Характеристика.*, Организация.*, Продавец.*, Партнер.*, ЗаказКлиента.*, Подразделение.*, Склад.*, Контрагент.*, Покупатель.*, Поставщик.*, Менеджер.*, Сделка.*, МенеджерСделки.*, ВидЗапасов.*, ГруппаФинансовогоУчета.*, ВидСделки, Регистратор.*, ПериодСекунда, День, Неделя, Декада, Месяц, Квартал, Полугодие, Год, ЭтоНовый} ИЗ (ВЫБРАТЬ ЕСТЬNULL(Продажи.ЗаказКлиента.Сделка, ЗНАЧЕНИЕ(Справочник.СделкиСКлиентами.ПустаяСсылка)) КАК Сделка, ЕСТЬNULL(Продажи.ЗаказКлиента.Сделка.Ответственный, ЗНАЧЕНИЕ(Справочник.Пользователи.ПустаяСсылка)) КАК МенеджерСделки, ЕСТЬNULL(Продажи.ЗаказКлиента.Менеджер, ЗНАЧЕНИЕ(Справочник.Пользователи.ПустаяСсылка)) КАК Менеджер, АналитикаНоменклатуры.Номенклатура КАК Номенклатура, АналитикаНоменклатуры.Характеристика КАК Характеристика, АналитикаПоПартнерам.Организация КАК Организация, АналитикаПоПартнерам.Организация КАК Продавец, АналитикаПоПартнерам.Партнер КАК Партнер, Продажи.ВидЗапасов КАК ВидЗапасов, Продажи.ВидЗапасов.ГруппаФинансовогоУчета КАК ГруппаФинансовогоУчета, Продажи.Подразделение КАК Подразделение, АналитикаНоменклатуры.МестоХранения КАК Склад, ВЫБОР КОГДА Продажи.ВидЗапасов.РеализацияЗапасовДругойОрганизации ТОГДА ВЫБОР КОГДА Продажи.ВидЗапасов.ВидЗапасовВладельца.ТипЗапасов = ЗНАЧЕНИЕ(Перечисление.ТипыЗапасов.КомиссионныйТовар) ТОГДА Продажи.ВидЗапасов.ВидЗапасовВладельца.Контрагент ИНАЧЕ Продажи.ВидЗапасов.ВидЗапасовВладельца.УстарелоПоставщик КОНЕЦ ИНАЧЕ ВЫБОР КОГДА Продажи.ВидЗапасов.ТипЗапасов = ЗНАЧЕНИЕ(Перечисление.ТипыЗапасов.КомиссионныйТовар) ТОГДА Продажи.ВидЗапасов.Контрагент ИНАЧЕ Продажи.ВидЗапасов.УстарелоПоставщик КОНЕЦ КОНЕЦ КАК Поставщик, ВЫБОР КОГДА Продажи.Регистратор = НЕОПРЕДЕЛЕНО ТОГДА NULL ИНАЧЕ Продажи.Регистратор КОНЕЦ КАК Регистратор, ВЫБОР КОГДА Продажи.ЗаказКлиента ССЫЛКА Документ.ЗаказКлиента ИЛИ Продажи.ЗаказКлиента ССЫЛКА Документ.ЗаявкаНаВозвратТоваровОтКлиента ТОГДА Продажи.ЗаказКлиента ИНАЧЕ НЕОПРЕДЕЛЕНО КОНЕЦ КАК ЗаказКлиента, ВЫБОР КОГДА АналитикаПоПартнерам.Контрагент ССЫЛКА Справочник.Контрагенты ТОГДА АналитикаПоПартнерам.Контрагент ИНАЧЕ NULL КОНЕЦ КАК Контрагент, ВЫБОР КОГДА АналитикаПоПартнерам.Контрагент ССЫЛКА Справочник.Организации ТОГДА АналитикаПоПартнерам.Контрагент ИНАЧЕ NULL КОНЕЦ КАК Покупатель, ВЫБОР КОГДА НЕ Продажи.ЗаказКлиента.Сделка.ВидСделки ЕСТЬ NULL ТОГДА Продажи.ЗаказКлиента.Сделка.ВидСделки.Наименование КОГДА Продажи.ЗаказКлиента ССЫЛКА Документ.ЗаказКлиента ИЛИ Продажи.ЗаказКлиента ССЫЛКА Документ.ЗаявкаНаВозвратТоваровОтКлиента ТОГДА "Продажи по заказам" ИНАЧЕ "Продажи без заказов" КОНЕЦ КАК ВидСделки, Продажи.КоличествоОборот КАК Количество, Продажи.СуммаВыручкиОборот КАК Выручка, Продажи.СуммаВыручкиРеглОборот КАК ВыручкаРегл, Продажи.СуммаВыручкиБезНДСОборот КАК ВыручкаБезНДС, ВЫБОР КОГДА Продажи.ТипЗапасов = ЗНАЧЕНИЕ(Перечисление.ТипыЗапасов.КомиссионныйТовар) ТОГДА Продажи.СуммаВыручкиОборот КОГДА ЕСТЬNULL(РасчетСебестоимости.Ссылка.ПредварительныйРасчет, ЛОЖЬ) ТОГДА ВЫРАЗИТЬ(Продажи.КоличествоОборот * ЕСТЬNULL(СтоимостьНоменклатуры.Стоимость, 0) КАК ЧИСЛО(15, 2)) ИНАЧЕ Продажи.СтоимостьОборот КОНЕЦ КАК Стоимость, ВЫБОР КОГДА Продажи.ТипЗапасов = ЗНАЧЕНИЕ(Перечисление.ТипыЗапасов.КомиссионныйТовар) ТОГДА Продажи.СуммаВыручкиБезНДСОборот КОГДА ЕСТЬNULL(РасчетСебестоимости.Ссылка.ПредварительныйРасчет, ЛОЖЬ) ТОГДА ВЫРАЗИТЬ(Продажи.КоличествоОборот * ЕСТЬNULL(СтоимостьНоменклатуры.СтоимостьБезНДС, 0) КАК ЧИСЛО(15, 2)) ИНАЧЕ Продажи.СтоимостьБезНДСОборот КОНЕЦ КАК СтоимостьБезНДС, ВЫБОР КОГДА Продажи.ТипЗапасов = ЗНАЧЕНИЕ(Перечисление.ТипыЗапасов.КомиссионныйТовар) ТОГДА Продажи.СуммаВыручкиРеглОборот КОГДА ЕСТЬNULL(РасчетСебестоимости.Ссылка.ПредварительныйРасчет, ЛОЖЬ) ТОГДА ВЫРАЗИТЬ(Продажи.КоличествоОборот * ЕСТЬNULL(СтоимостьНоменклатуры.СтоимостьРегл, 0) КАК ЧИСЛО(15, 2)) ИНАЧЕ Продажи.СтоимостьРеглОборот КОНЕЦ КАК СтоимостьРегл, ВЫБОР КОГДА Продажи.ТипЗапасов = ЗНАЧЕНИЕ(Перечисление.ТипыЗапасов.КомиссионныйТовар) ТОГДА 0 КОГДА ЕСТЬNULL(РасчетСебестоимости.Ссылка.ПредварительныйРасчет, ЛОЖЬ) ТОГДА ВЫРАЗИТЬ(Продажи.КоличествоОборот * ЕСТЬNULL(СтоимостьНоменклатуры.СтоимостьДопРасходы, 0) КАК ЧИСЛО(15, 2)) ИНАЧЕ Продажи.ДопРасходыОборот КОНЕЦ КАК ДопРасходы, ВЫБОР КОГДА Продажи.ТипЗапасов = ЗНАЧЕНИЕ(Перечисление.ТипыЗапасов.КомиссионныйТовар) ТОГДА 0 КОГДА ЕСТЬNULL(РасчетСебестоимости.Ссылка.ПредварительныйРасчет, ЛОЖЬ) ТОГДА ВЫРАЗИТЬ(Продажи.КоличествоОборот * ЕСТЬNULL(СтоимостьНоменклатуры.СтоимостьДопРасходыБезНДС, 0) КАК ЧИСЛО(15, 2)) ИНАЧЕ Продажи.ДопРасходыБезНДСОборот КОНЕЦ КАК ДопРасходыБезНДС, Продажи.ПериодСекунда КАК ПериодСекунда, Продажи.ПериодДень КАК День, Продажи.ПериодНеделя КАК Неделя, Продажи.ПериодДекада КАК Декада, Продажи.ПериодМесяц КАК Месяц, Продажи.ПериодКвартал КАК Квартал, Продажи.ПериодПолугодие КАК Полугодие, Продажи.ПериодГод КАК Год {ВЫБРАТЬ ЗаказКлиента.*, Сделка.*, МенеджерСделки, Подразделение.*, Номенклатура.*, Характеристика.*, Склад.*, Организация.*, Продавец.*, Партнер.*, Контрагент.*, Покупатель.*, Поставщик.*, Менеджер.*, ВидЗапасов.*, ГруппаФинансовогоУчета.*, Регистратор, ПериодСекунда, День, Неделя, Декада, Месяц, Квартал, Полугодие, Год, ВидСделки} ИЗ РегистрНакопления.ВыручкаИСебестоимостьПродаж.Обороты({(&НачалоПериода)}, {(&ОкончаниеПериода)}, Авто, {(ЕСТЬNULL(ЗаказКлиента.Сделка, ЗНАЧЕНИЕ(Справочник.СделкиСКлиентами.ПустаяСсылка))).* КАК Сделка, (ЕСТЬNULL(ЗаказКлиента.Сделка.Ответственный, ЗНАЧЕНИЕ(Справочник.Пользователи.ПустаяСсылка))).* КАК МенеджерСделки, (ЕСТЬNULL(ЗаказКлиента.Менеджер, ЗНАЧЕНИЕ(Справочник.Пользователи.ПустаяСсылка))).* КАК Менеджер, (ВЫБОР КОГДА ВидЗапасов.РеализацияЗапасовДругойОрганизации ТОГДА ВЫБОР КОГДА ВидЗапасов.ВидЗапасовВладельца.ТипЗапасов = ЗНАЧЕНИЕ(Перечисление.ТипыЗапасов.КомиссионныйТовар) ТОГДА ВидЗапасов.ВидЗапасовВладельца.Контрагент ИНАЧЕ ВидЗапасов.ВидЗапасовВладельца.УстарелоПоставщик КОНЕЦ ИНАЧЕ ВЫБОР КОГДА ВидЗапасов.ТипЗапасов = ЗНАЧЕНИЕ(Перечисление.ТипыЗапасов.КомиссионныйТовар) ТОГДА ВидЗапасов.Контрагент ИНАЧЕ ВидЗапасов.УстарелоПоставщик КОНЕЦ КОНЕЦ).* КАК Поставщик, (ВидЗапасов.ГруппаФинансовогоУчета).* КАК ГруппаФинансовогоУчета, (ВЫБОР КОГДА НЕ ЗаказКлиента.Сделка.ВидСделки ЕСТЬ NULL ТОГДА ЗаказКлиента.Сделка.ВидСделки.Наименование КОГДА ЗаказКлиента ССЫЛКА Документ.ЗаказКлиента ИЛИ ЗаказКлиента ССЫЛКА Документ.ЗаявкаНаВозвратТоваровОтКлиента ТОГДА "Продажи по заказам" ИНАЧЕ "Продажи без заказов" КОНЕЦ) КАК ВидСделки}) КАК Продажи {ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.АналитикаУчетаНоменклатуры КАК АналитикаНоменклатуры ПО Продажи.АналитикаУчетаНоменклатуры = АналитикаНоменклатуры.КлючАналитики} {ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.АналитикаУчетаПоПартнерам КАК АналитикаПоПартнерам ПО Продажи.АналитикаУчетаПоПартнерам = АналитикаПоПартнерам.КлючАналитики} {ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.СтоимостьТоваров КАК СтоимостьНоменклатуры ПО Продажи.АналитикаУчетаНоменклатуры = СтоимостьНоменклатуры.АналитикаУчетаНоменклатуры И (АналитикаПоПартнерам.Организация = СтоимостьНоменклатуры.Орган